# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. PEYGAMBER VE SAHABE DÖNEMİNDE HADİSLERİN SÖZLÜ AKTARIMI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SÖZLÜ AKTARIMI GÜÇLENDİREN UNSURLAR</text>\n  <text x="34" y="88" font-size="10.8" fill="#1e3a8a">• Hz. Peygamber\'in (sav) açık, tane tane ve önemli</text>\n  <text x="44" y="104" font-size="10.5" fill="#1e3a8a">sözleri üç kez tekrarlayarak konuşması (Cevâmiu\'l-kelim).</text>\n  <text x="34" y="126" font-size="10.8" fill="#1e3a8a">• Mescid-i Nebevî\'deki Ashâb-ı Suffe\'nin ilim ve ezber mesaisi.</text>\n  <text x="34" y="148" font-size="10.8" fill="#1e3a8a">• Sahabilerin nöbetleşe (münâvebe usulüyle) dersleri</text>\n  <text x="44" y="164" font-size="10.5" fill="#1e3a8a">dinleyip birbirine aktarması (Hz. Ömer ve komşusu).</text>\n  <text x="34" y="186" font-size="10.8" fill="#1e3a8a">• Müzâkere halkaları ve sünnetin fiilen yaşanması.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">MÜKSİRÛN (EN ÇOK HADİS RİVAYET EDEN 7 SAHABİ)</text>\n  <text x="370" y="88" font-size="10.8" font-weight="bold" fill="#15803d">1000\'den fazla hadis rivayet eden sahabiler:</text>\n  <text x="370" y="108" font-size="10.6" fill="#14532d">1. Ebû Hüreyre (5374 hadis — Suffe\'nin öncüsü)</text>\n  <text x="370" y="125" font-size="10.6" fill="#14532d">2. Abdullah b. Ömer (2630) · 3. Enes b. Mâlik (2286)</text>\n  <text x="370" y="142" font-size="10.6" fill="#14532d">4. Hz. Âişe (2210) · 5. Abdullah b. Abbâs (1660)</text>\n  <text x="370" y="159" font-size="10.6" fill="#14532d">6. Câbir b. Abdullah (1540) · 7. Ebû Saîd el-Hudrî (1170)</text>\n  <text x="370" y="182" font-size="10.5" font-weight="bold" fill="#166534">• Tesebbüt ve İhtiyat: Hz. Ebû Bekir ve Hz. Ömer\'in</text>\n  <text x="380" y="198" font-size="10.2" fill="#14532d">hadis rivayetinde şahit istemesi ve titizliği.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Bizden bir söz işitip de onu işittiği gibi başkasına ulaştıran kimsenin Allah yüzünü ağartsın.» (Tirmizî, İlim, 7)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ASR-I SAADET VE SAHABE DÖNEMİNDE YAZILI AKTARIM (KİTÂBET VE SAHÎFELER)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">YAZIM İZNİ VE RESMÎ BELGELER</text>\n  <text x="34" y="88" font-size="10.8" fill="#713f12">• İlk başta Kur\'an ayetleriyle karışmaması için</text>\n  <text x="44" y="104" font-size="10.4" fill="#713f12">hadis yazımı sınırlandırılmış; bu tehlike kalkınca</text>\n  <text x="44" y="120" font-size="10.4" fill="#713f12">Hz. Peygamber (sav) yazıma izin ve teşvik vermiştir.</text>\n  <text x="34" y="142" font-size="10.8" font-weight="bold" fill="#a16207">• Resmî Yazılı Belgeler:</text>\n  <text x="44" y="159" font-size="10.4" fill="#713f12">Medine Vesikası, Hudeybiye Antlaşması, İslam\'a</text>\n  <text x="44" y="175" font-size="10.4" fill="#713f12">davet mektupları, Amr b. Hazm\'a verilen zekât ve</text>\n  <text x="44" y="191" font-size="10.4" fill="#713f12">diyet talimatnamesi, Ebû Şâh için yazılan hutbe.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ÖZEL HADİS SAHÎFELERİ (İLK YAZILI MECMUALAR)</text>\n  <text x="370" y="88" font-size="10.8" font-weight="bold" fill="#7e22ce">• es-Sahîfetü\'s-Sâdıka (Abdullah b. Amr b. Âs):</text>\n  <text x="380" y="104" font-size="10.4" fill="#581c87">Bizzat Hz. Peygamber\'in izniyle yazılan ~1000 hadis.</text>\n  <text x="370" y="126" font-size="10.8" font-weight="bold" fill="#7e22ce">• es-Sahîfetü\'s-Sahîha (Hemmâm b. Münebbih):</text>\n  <text x="380" y="142" font-size="10.4" fill="#581c87">Ebû Hüreyre\'den yazılıp günümüze ulaşan 138 hadis.</text>\n  <text x="370" y="164" font-size="10.8" fill="#581c87">• Hz. Ali\'nin Sahîfesi (Diyet ve hukuk hükümleri)</text>\n  <text x="370" y="182" font-size="10.8" fill="#581c87">• Semüre b. Cündeb ve Câbir b. Abdullah\'ın Sahîfeleri</text>\n  <text x="370" y="200" font-size="10.8" fill="#581c87">• Sa\'d b. Ubâde ve Enes b. Mâlik\'in yazılı nüshaları</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«İlmi yazıyla kayıt altına alınız (bağlayınız).» ve «Sağ elinden (yazıdan) yardım iste!» hadisleri kitâbetin temelidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÂBİÎN DÖNEMİ: RİHLE, İSNAT SİSTEMİ VE RESMÎ TEDVİN (H. I-II. ASIR)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">İLİM MERKEZLERİ, RİHLE VE İSNAT</text>\n  <text x="34" y="88" font-size="10.8" fill="#7c2d12">• Sahabilerin farklı şehirlere yerleşmesiyle Medine,</text>\n  <text x="44" y="104" font-size="10.4" fill="#7c2d12">Mekke, Kûfe, Basra, Şam, Mısır ve Yemen ilim</text>\n  <text x="44" y="120" font-size="10.4" fill="#7c2d12">merkezleri doğmuştur.</text>\n  <text x="34" y="142" font-size="10.8" font-weight="bold" fill="#c2410c">• er-Rihle fî Talebi\'l-Hadîs (Hadis Yolculukları):</text>\n  <text x="44" y="158" font-size="10.4" fill="#7c2d12">Tek bir hadisi kaynağından duymak için yapılan</text>\n  <text x="44" y="174" font-size="10.4" fill="#7c2d12">uzun ilim seyahatleri (Câbir b. Abdullah\'ın Mısır yolculuğu).</text>\n  <text x="34" y="196" font-size="10.8" font-weight="bold" fill="#c2410c">• İsnat Sorulması: «Bize ravilerinizin adını söyleyiniz!»</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">RESMÎ TEDVİN HAREKETİ (HİCRİ I. ASIR SONU)</text>\n  <text x="370" y="88" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Tedvin (Dağınık Sahîfeleri Bir Araya Toplama):</text>\n  <text x="380" y="104" font-size="10.4" fill="#1e3a8a">Halife Ömer b. Abdülazîz\'in (v. 101/720) valilere ve</text>\n  <text x="380" y="120" font-size="10.4" fill="#1e3a8a">âlimlere gönderdiği emirle resmen başlamıştır.</text>\n  <text x="370" y="142" font-size="10.8" font-weight="bold" fill="#1d4ed8">• İlk Resmî Tedvin Âlimi:</text>\n  <text x="380" y="158" font-size="10.4" fill="#1e3a8a">İbn Şihâb ez-Zührî (v. 124/742) ve Ebû Bekir b. Hazm.</text>\n  <text x="370" y="180" font-size="10.8" fill="#1e3a8a">• Amaç: Âlimlerin vefatıyla ilmin kaybolmasını</text>\n  <text x="380" y="196" font-size="10.4" fill="#1e3a8a">önlemek ve sahih hadisleri koruma altına almaktır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hadisler baştan itibaren hem güçlü HAFIZA (ezber) hem de YAZI (kitâbet/sahîfe) ile çift yönlü korunmuştur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
